FlexmonsterToolbar.prototype.connectLocalCSVHandler=function(){this.pivot.connectTo({type:"csv",browseForFile:!0})};FlexmonsterToolbar.prototype.connectLocalJSONHandler=function(){this.pivot.connectTo({type:"json",browseForFile:!0})};FlexmonsterToolbar.prototype.connectRemoteCSV=function(){this.showConnectToRemoteCSVDialog()};FlexmonsterToolbar.prototype.connectRemoteJSON=function(){this.showConnectToRemoteJsonDialog()};FlexmonsterToolbar.prototype.connectOLAP=function(){this.showConnectToOLAPDialog()};
FlexmonsterToolbar.prototype.connectElastic=function(){this.showConnectToElasticDialog()};FlexmonsterToolbar.prototype.openLocalReport=function(){this.pivot.open()};FlexmonsterToolbar.prototype.openRemoteReport=function(){this.showOpenRemoteReportDialog()};FlexmonsterToolbar.prototype.saveHandler=function(){this.pivot.save("report.json","file")};FlexmonsterToolbar.prototype.gridHandler=function(){this.pivot.showGrid()};
FlexmonsterToolbar.prototype.chartsHandler=function(a){var b=((this.pivot.getOptions()||{}).chart||{}).multipleMeasures,c=this.getElementById("fm-tab-charts-multiple");null!=c&&this.disableMultipleValues(a,b,c);this.pivot.showCharts(a,b)};
FlexmonsterToolbar.prototype.chartsMultipleHandler=function(){var a=(this.pivot.getOptions()||{}).chart||{},b=a.type;a=!a.multipleMeasures;var c=this.getElementById("fm-tab-charts-multiple");a?this.addClass(c,"fm-selected"):this.removeClass(c,"fm-selected");"pie"==b||"stacked_column"==b||"column_line"==b?this.removeClass(c,"fm-selected"):this.pivot.showCharts(b,a)};
